+
+    @Test
+    void cancellingAConfirmedReservationNotifiesGovernanceAndFinance() {
+        Reservation standard = service.create(stay(102, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
+        service.confirm(standard.id());
+
+        service.cancel(standard.id());
+
+        List<Message> sent = sentMessages.all();
+        assertEquals(5, sent.size());
+        Message governanceMessage = sent.get(3);
+        Message financeMessage = sent.get(4);
+
+        assertEquals("governanca@pousadamarealta.com.br", governanceMessage.to());
+        assertEquals("Reserva cancelada - quarto 102", governanceMessage.subject());
+        assertTrue(governanceMessage.body().contains("10/03/2027"));
+        assertTrue(governanceMessage.body().contains("11/03/2027"));
+
+        assertEquals("financeiro@pousadamarealta.com.br", financeMessage.to());
+        assertEquals("Reembolso - reserva " + standard.id(), financeMessage.subject());
+        assertTrue(financeMessage.body().contains("R$ 249,90"));
+    }
+
+    @Test
+    void cancellingANonRefundableReservationDoesNotNotifyFinance() {
+        Reservation nonRefundable = service.create(stay(201, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
+        service.confirm(nonRefundable.id());
+
+        service.cancel(nonRefundable.id());
+
+        List<Message> sent = sentMessages.all();
+        assertEquals(4, sent.size());
+        Message governanceMessage = sent.get(3);
+        assertEquals("governanca@pousadamarealta.com.br", governanceMessage.to());
+        assertEquals("Reserva cancelada - quarto 201", governanceMessage.subject());
+    }
+
+    @Test
+    void cancellingAPendingReservationDoesNotNotifyAnyone() {
+        Reservation pending = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
+
+        service.cancel(pending.id());
+
+        List<Message> sent = sentMessages.all();
+        assertEquals(0, sent.size());
+    }
 }
