     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	import java.util.ArrayList;
     9	import java.util.List;
    10	
    11	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    12	public final class ReservationService {
    13	
    14	    static final String HOTEL_NAME = "Pousada Maré Alta";
    15	
    16	    private final Rooms rooms;
    17	    private final ReservationStore store;
    18	    private final PriceCalculator priceCalculator;
    19	    private final EmailSender emailSender;
    20	    private final List<ReservationNotifier> notifiers;
    21	
    22	    public ReservationService(
    23	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    24	        this(rooms, store, priceCalculator, emailSender, new ArrayList<>());
    25	    }
    26	
    27	    public ReservationService(
    28	            Rooms rooms,
    29	            ReservationStore store,
    30	            PriceCalculator priceCalculator,
    31	            EmailSender emailSender,
    32	            List<ReservationNotifier> notifiers) {
    33	        this.rooms = rooms;
    34	        this.store = store;
    35	        this.priceCalculator = priceCalculator;
    36	        this.emailSender = emailSender;
    37	        this.notifiers = notifiers;
    38	    }
    39	
    40	    public synchronized Reservation create(NewReservation request) {
    41	        if (!request.checkOut().isAfter(request.checkIn())) {
    42	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    43	        }
    44	        if (request.guests() < 1) {
    45	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    46	        }
    47	        Room room = rooms.find(request.roomNumber())
    48	                .orElseThrow(() -> new HotelException(
    49	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    50	        if (request.guests() > room.capacity()) {
    51	            throw new HotelException(
    52	                    ErrorCode.CAPACITY_EXCEEDED,
    53	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    54	        }
    55	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    56	            throw new HotelException(
    57	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    58	        }
    59	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    60	        return store.add(request, price);
    61	    }
    62	
    63	    public Reservation find(long reservationId) {
    64	        return store.find(reservationId)
    65	                .orElseThrow(() -> new HotelException(
    66	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    67	    }
    68	
    69	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    70	    public synchronized Reservation confirm(long reservationId) {
    71	        Reservation reservation = find(reservationId);
    72	        if (reservation.status() != ReservationStatus.PENDING) {
    73	            throw notAllowed(reservation, "confirm");
    74	        }
    75	        reservation.confirmPayment();
    76	        store.update(reservation);
    77	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    78	        emailSender.send(
    79	                reservation.guest().email(),
    80	                "Reserva confirmada - " + HOTEL_NAME,
    81	                confirmationEmailBody(reservation, receipt));
    82	        for (ReservationNotifier notifier : notifiers) {
    83	            notifier.onReservationConfirmed(reservation);
    84	        }
    85	        return reservation;
    86	    }
    87	
    88	    /**
    89	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    90	     * reservation was never paid, so nothing comes back).
    91	     */
    92	    public synchronized Reservation cancel(long reservationId) {
    93	        Reservation reservation = find(reservationId);
    94	        if (reservation.status() != ReservationStatus.PENDING
    95	                && reservation.status() != ReservationStatus.CONFIRMED) {
    96	            throw notAllowed(reservation, "cancel");
    97	        }
    98	        BigDecimal refund = switch (reservation.ratePlan()) {
    99	            case STANDARD -> reservation.amountPaid();
   100	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   101	        };
   102	        reservation.cancel(refund);
   103	        store.update(reservation);
   104	        for (ReservationNotifier notifier : notifiers) {
   105	            notifier.onReservationCancelled(reservation);
   106	        }
   107	        return reservation;
   108	    }
   109	
   110	    public synchronized Reservation checkIn(long reservationId) {
   111	        Reservation reservation = find(reservationId);
   112	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   113	            throw notAllowed(reservation, "check in");
   114	        }
   115	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   116	        store.update(reservation);
   117	        return reservation;
   118	    }
   119	
   120	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   121	    public synchronized ReservationReceipt checkOut(long reservationId) {
   122	        Reservation reservation = find(reservationId);
   123	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   124	            throw notAllowed(reservation, "check out");
   125	        }
   126	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   127	        store.update(reservation);
   128	        return new ReservationReceipt(reservation, roomOf(reservation));
   129	    }
   130	
   131	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   132	    public ReservationReceipt receiptCopy(long reservationId) {
   133	        Reservation reservation = find(reservationId);
   134	        if (!reservation.isPaid()) {
   135	            throw notAllowed(reservation, "issue a receipt for");
   136	        }
   137	        return new ReservationReceipt(reservation, roomOf(reservation));
   138	    }
   139	
   140	    private Room roomOf(Reservation reservation) {
   141	        return rooms.find(reservation.roomNumber()).orElseThrow();
   142	    }
   143	
   144	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   145	        return "Olá, " + reservation.guest().name() + "!\n\n"
   146	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   147	                + receipt.text() + "\n"
   148	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   149	                + "Até breve!\n";
   150	    }
   151	
   152	    private static HotelException notAllowed(Reservation reservation, String operation) {
   153	        return new HotelException(
   154	                ErrorCode.OPERATION_NOT_ALLOWED,
   155	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   156	    }
   157	}
