    @Test
    void confirmingNotifiesGovernanceAndFinance() {
        Reservation reservation = service.create(stay(102, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));

        service.confirm(reservation.id());

        List<Message> sent = sentMessages.all();
        assertEquals(3, sent.size());
        Message governanceMessage = sent.get(1);
        Message financeMessage = sent.get(2);

        assertEquals("governanca@pousadamarealta.com.br", governanceMessage.to());
        assertEquals("Reserva confirmada - quarto 102", governanceMessage.subject());
        assertTrue(governanceMessage.body().contains("10/03/2027"));
        assertTrue(governanceMessage.body().contains("11/03/2027"));
        assertTrue(governanceMessage.body().contains("1 hóspede(s)"));

        assertEquals("financeiro@pousadamarealta.com.br", financeMessage.to());
        assertEquals("Pagamento recebido - reserva " + reservation.id(), financeMessage.subject());
        assertTrue(financeMessage.body().contains("R$"));
    }

